from groq import Groq

client = Groq()

def chat(prompt: str) -> str:
    r = client.chat.completions.create(
        model="{{model_name}}",
        messages=[{"role": "user", "content": prompt}],
    )
    return r.choices[0].message.content

if __name__ == "__main__":
    print(chat("hi"))
